"""Build a local, linked IDOL evidence gallery from explicitly selected runs."""
import argparse
from datetime import datetime, timezone
import html
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1] / 'reports/idol'


def escape(value): return html.escape(str(value), quote=True)


def run_section(run_id, record):
    status = record['status']
    source = record.get('input', {}).get('source', 'Unknown input').replace('\\', '/').split('/')[-1]
    figures = []
    for filename, label in [('input-native.png', 'Input · native crop')] + [(p['file'], p['name'].title()) for p in record.get('poses', [])]:
        if (ROOT / run_id / filename).is_file():
            figures.append(f'<figure><a href="{run_id}/{filename}"><img loading="lazy" src="{run_id}/{filename}" alt="{escape(source)}: {escape(label)}"></a><figcaption>{escape(label)}</figcaption></figure>')
    stages = record.get('stages', {})
    max_time = max(stages.values(), default=1)
    bars = ''.join(f'<div class="bar-row"><span>{escape(name.replace("_", " "))}</span><div class="track"><i style="width:{100 * seconds / max_time:.2f}%"></i></div><b>{seconds:.2f}s</b></div>' for name, seconds in stages.items())
    neural = stages.get('image_to_uv', 0) + stages.get('uv_to_gaussians', 0)
    rows = ''.join(f'<tr><td>{escape(p["name"])}</td><td>{p["seconds"] * 1000:.1f} ms</td><td>{p["visiblePixels"]:,}</td><td>{p["maxCenterDisplacement"]:.3f}</td><td>{100 * p["meanRelativeScaleChange"]:.2f}%</td></tr>' for p in record.get('poses', []))
    error = f'<p class="notice warn">Retained failure: {escape(record.get("error"))}</p>' if status != 'native-passed' else ''
    notes_path = ROOT / 'observations.json'
    observations = json.loads(notes_path.read_text()).get(run_id, {}) if notes_path.is_file() else {}
    notes = '<p class="notice"><strong>Visual inspection: </strong>' + ' '.join(escape(note) for note in observations.get('notes', [])) + '</p>' if observations else ''
    return f'''<section id="{run_id}"><div class="section-label">Recorded run / {escape(status)}</div>
      <h2>{escape(source)} <span class="badge {'ok' if status == 'native-passed' else 'pending'}">{escape(status)}</span></h2>
      <p class="muted">Shape: {escape(record.get('shapeMode', 'unknown'))}. One image, FP32, original 1536² UV atlas. <a href="{run_id}/metrics.json">Metrics</a> · <a href="{run_id}/run.json">Command &amp; hashes</a> · <a href="{run_id}/console.log">Console</a></p>
      {error}<div class="gallery">{''.join(figures)}</div>{notes}
      <div class="stats"><div><strong>{record.get('gaussianCount', 0):,}</strong><span>Native Gaussians</span></div><div><strong>{neural:.2f}s</strong><span>Image → UV → attributes only</span></div><div><strong>{record.get('wallSeconds', 0):.1f}s</strong><span>Whole instrumented trial</span></div><div><strong>{record.get('peakAllocatedBytes', 0)/1024**3:.2f} / {record.get('peakReservedBytes', 0)/1024**3:.2f}</strong><span>Peak allocated / reserved GiB</span></div></div>
      <details><summary>Stage timings and pose diagnostics</summary><div class="bars">{bars}</div>
      <p class="small">Cold model construction/load, integrity hashing, diagnostic export and eight native renders are included in the trial wall time. CPU matting and Docker startup are separate. One execution per successful case; no warmed multi-run latency claim.</p>
      <div class="table-scroll"><table><thead><tr><th>Pose</th><th>Deform + render</th><th>Non-white pixels</th><th>Max movement¹</th><th>Mean scale change²</th></tr></thead><tbody>{rows}</tbody></table></div>
      <p class="small">¹ Relative to front-pose centers, native coordinates. ² Relative to front-pose sizes: native nearest-neighbor scales are recomputed after posing. Timings include native visibility diagnostics, not just drawing; they are not browser FPS.</p></details></section>'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('runs', nargs='+')
    parser.add_argument('--portability-run', help='Link a later independently validated corrective-stage report')
    args = parser.parse_args()
    records = []
    for run_id in args.runs:
        if not re.fullmatch(r'native-\d{8}-\d{6}-[0-9a-f]{6}', run_id): raise ValueError('Expected a native run ID')
        records.append((run_id, json.loads((ROOT / run_id / 'metrics.json').read_text())))
    passed = [(name, data) for name, data in records if data['status'] == 'native-passed']
    sections = ''.join(run_section(name, data) for name, data in records)
    measured = passed[0][1] if passed else records[-1][1]
    feasibility = measured.get('exportFeasibility', {})
    pose_basis = feasibility.get('sourcePoseBasisBytes', 0) / 1e6
    expanded = feasibility.get('naivePerGaussianPoseBasisBytes', 0) / 1e6
    decision = 'Native reconstruction is feasible; browser promotion remains unproven.' if passed else 'Native trial has not passed; retain the failure before further integration.'
    summary = dict(generatedAt=datetime.now(timezone.utc).isoformat(), runs=args.runs,
                   passedRuns=len(passed), totalRuns=len(records), decision=decision,
                   browserPromoted=False, qualityWinner=None)
    body = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>IDOL · Native feasibility / Gaussian Avatar Lab</title><style>
:root{--ink:#172b31;--muted:#5b7175;--paper:#f4f5ef;--line:#d6dfd8;--green:#176c5b;--amber:#835923;--soft:#e5eee7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,Segoe UI,sans-serif}a{color:var(--green);text-underline-offset:3px}header,main,footer{max-width:1240px;margin:auto;padding:24px 42px}header{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);font-size:12px;letter-spacing:.08em}.hero{padding:54px 0 28px}.section-label{color:var(--green);font-size:11px;font-weight:750;letter-spacing:.14em;text-transform:uppercase}h1{font:500 clamp(42px,5vw,72px)/1.08 Georgia,serif;letter-spacing:-.04em;max-width:900px;margin:18px 0}h1 em{font-weight:400;color:var(--green)}h2{font:500 34px/1.25 Georgia,serif;letter-spacing:-.02em;margin:12px 0}h3{font-size:17px}p{max-width:960px}.lede{font-size:20px;color:var(--muted);max-width:900px}.muted,.small{color:var(--muted)}.small{font-size:12px}.notice{background:var(--soft);border-left:3px solid var(--green);padding:18px 24px;border-radius:0 9px 9px 0;max-width:none}.warn{background:#f4ead9;border-color:var(--amber);color:#674a26}section{padding:36px 0;border-top:1px solid var(--line);scroll-margin-top:18px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:10px;overflow:hidden;margin:24px 0}.stats>div{background:#fff;padding:20px}.stats strong{display:block;font:32px/1.2 Georgia,serif}.stats span{font-size:11px;color:var(--muted);display:block;margin-top:8px}.pipeline{display:grid;grid-template-columns:repeat(5,1fr);gap:13px;margin:26px 0}.step{padding:20px;background:#fff;border:1px solid var(--line);border-radius:10px;position:relative}.step:not(:last-child):after{content:'→';position:absolute;right:-12px;top:42%;color:var(--green);z-index:1}.step b,.step span{display:block}.step span{font-size:12px;color:var(--muted);margin-top:8px}.step small{color:var(--green);font:12px ui-monospace,monospace}.columns{display:grid;grid-template-columns:1fr 1fr;gap:26px}.card{padding:22px 26px;border:1px solid var(--line);border-radius:10px;background:white}.gallery{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:24px 0}.gallery figure{margin:0;border:1px solid var(--line);background:white;border-radius:9px;overflow:hidden}.gallery img{display:block;width:100%;aspect-ratio:640/896;object-fit:contain;background:white}.gallery figcaption{font-size:12px;padding:9px 12px;border-top:1px solid var(--line)}.badge{font:11px system-ui,sans-serif;display:inline-block;vertical-align:middle;padding:5px 10px;border-radius:30px}.ok{background:#d4eee0;color:#225c45}.pending{background:#f5e5ca;color:#835923}details{background:#fff;border:1px solid var(--line);border-radius:9px;padding:18px 24px}summary{cursor:pointer;font-weight:600}.bars{margin-top:20px}.bar-row{display:grid;grid-template-columns:240px 1fr 75px;gap:14px;align-items:center;font-size:12px;margin:9px 0}.track{height:8px;background:#edf1ed;border-radius:5px;overflow:hidden}.track i{display:block;min-width:2px;height:100%;background:var(--green)}table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.04em}td,th{padding:12px;border-bottom:1px solid var(--line)}td:first-child{font-weight:600}.table-scroll{overflow:auto}code{font-size:12px;overflow-wrap:anywhere}.equation{font:16px/1.7 ui-monospace,monospace;padding:23px;background:#1b3437;color:#dceae3;border-radius:10px}footer{font-size:12px;color:var(--muted);padding-top:30px;padding-bottom:50px}li{margin:8px 0}@media(max-width:850px){header,main,footer{padding-left:20px;padding-right:20px}.pipeline{grid-template-columns:1fr}.step:not(:last-child):after{content:'↓';right:18px;top:auto;bottom:-19px}.gallery{grid-template-columns:repeat(3,1fr)}.columns{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.bar-row{grid-template-columns:150px 1fr 65px}}@media(max-width:520px){.gallery{grid-template-columns:repeat(2,1fr)}h2{font-size:28px}.bar-row{grid-template-columns:120px 1fr 55px;font-size:10px}}@media print{details{display:block}.hero{padding-top:20px}section{break-inside:avoid}.gallery{grid-template-columns:repeat(5,1fr)}}
</style></head><body><header><span>GAUSSIAN AVATAR LAB / RESEARCH NOTE 03</span><span>09 SEPTEMBER 2026</span></header><main>
<div class="hero"><div class="section-label">Generation research · independent UV-based challenger</div><h1>IDOL runs natively.<br><em>A different animation contract.</em></h1><p class="lede">Single-image reconstruction is only half the question. Can its native Gaussian deformation become an independently controlled, portable avatar?</p><p class="notice"><strong>@@DECISION@@</strong> @@PASSED@@ successful native smoke runs out of @@TOTAL@@ retained attempts. No quality winner, new default, or IDOL browser integration is claimed.</p></div>
<section><div class="section-label">01 / What was executed</div><h2>One isolated family. The original pipeline stays intact.</h2><div class="columns"><div class="card"><h3>Reconstruction route</h3><p><a href="https://arxiv.org/abs/2412.14963">IDOL: Instant Photorealistic 3D Human Creation from a Single Image</a>, Zhuang et al., CVPR 2025. Its feed-forward network predicts structured UV Gaussian attributes from an input image.</p><p>We use the <a href="https://github.com/yiyuzhuang/IDOL/tree/9fd9296c28e8f8f9ed5f5c594f3df1574b8ec82d">pinned author implementation</a> and <a href="https://huggingface.co/yiyuzhuang/IDOL/tree/3c80ec956f9bede01d9fbb3917ca229f8d2673b1">author-hosted weights/cache</a>. No retraining, lower-resolution substitution, or different checkpoint.</p></div><div class="card"><h3>Compatibility trial, not exact environment replication</h3><p>RTX 4090 · PyTorch 2.3.0 · CUDA 12.1 · PyTorch3D 0.7.6. The author recommends 2.3.1 / 11.8 / 0.7.7. A dedicated IDOL Python volume reuses the cached CUDA image; LHM/LHM++ environments and the default avatar are not modified.</p><p>Native execution is offline. Models, source and templates are read-only; only scoped scratch and run evidence are writable. Full hashes, environment versions and failures are retained.</p></div></div></section>
<section><div class="section-label">02 / Pipeline in order</div><h2>Photo → UV attributes → posed Gaussians → native pixels</h2><div class="pipeline"><div class="step"><small>01 / INPUT</small><b>Alpha + framing</b><span>CPU U2Net; native 0.85 framing, 896 × 640 crop. Supplied or explicitly zero body shape.</span></div><div class="step"><small>02 / ENCODE</small><b>Sapiens + transformer</b><span>Native 1024 × 736 encoder input, 40 hidden layers; 16-block UV decoder.</span></div><div class="step"><small>03 / RECONSTRUCT</small><b>1536² UV atlas</b><span>Sample 200,800 Gaussians: color, offsets, scale multipliers and axis-angle orientation.</span></div><div class="step"><small>04 / ANIMATE</small><b>SMPL-X + correctives</b><span>55-joint skinning, body/face shape directions and pose-dependent offsets.</span></div><div class="step"><small>05 / RENDER</small><b>Native covariance</b><span>Recompute posed-neighbor sizes, transform full covariance, antialiased splat rasterization.</span></div></div><p class="small">The supplied-shape author example is a pipeline control. The LHM fixture uses zero betas; it is not equivalent to an estimated-shape run. The released runner consumes shape coefficients rather than inferring them in this path.</p></section>
@@RUNS@@
<section><div class="section-label">03 / Why export is a separate gate</div><h2>Same skeleton family ≠ the same deformation algorithm.</h2><div class="table-scroll"><table><thead><tr><th>Part</th><th>Native IDOL behavior</th><th>Browser implication</th></tr></thead><tbody><tr><td>Pose schema</td><td>189 parameters: scale/trans/root/body, 10 betas, full hands, jaw/eyes, 10 expressions</td><td>Explicit schema and hand-mean mapping; not the current 100-expression stream</td></tr><tr><td>Bindings</td><td>55 weights queried at predicted canonical centers, with face/hand/outside mask overrides</td><td>Export exact weights and rest conventions; do not truncate influences silently</td></tr><tr><td>Pose correctives</td><td>486 rotation-feature dimensions; @@BASIS@@ MB source basis</td><td>A naive per-Gaussian dense basis is @@EXPANDED@@ MB, before other arrays</td></tr><tr><td>Gaussian size</td><td>Recomputed from three nearest neighbors in posed space</td><td>Fixed rest-pose scales are an approximation, not native parity</td></tr><tr><td>Covariance</td><td>Full blended transform, including nonorthogonal components</td><td>Compare covariance, not just center + unit quaternion</td></tr></tbody></table></div><div class="equation">s(pose) = √max(mean 3-neighbor distance², 10⁻⁷) · (radius + 1)<br>Σ(pose) = R_deformed · diag(s²) · R_deformedᵀ</div><p>These sizes are measured dense-array costs, not a lower bound or a shipped browser package. Sparse support, shared vertex bases and compression are candidates for a separately measured portability spike.</p><p class="notice warn"><strong>Not a portable rig yet.</strong> The saved NPZ files are diagnostic attributes and native pose fixtures. A posed PLY, screenshots, or cached animation frames would not prove arbitrary web animation. IDOL has not passed browser parity, Mixamo retargeting, remote-signal mapping, or Unity/Quest tests.</p></section>
<section><div class="section-label">04 / Fidelity and retained failure</div><h2>Keep the differences visible.</h2><div class="columns"><div><h3>Checks and adaptations</h3><ul><li>All public model/cache files are SHA-256 checked. Main checkpoint loading uses <code>weights_only=True</code>; TorchScript executes only in the offline container.</li><li>Our neutral template passes seven NPZ-versus-PKL serialization checks. This tests the same arrays through both native loaders, not equality to an unavailable original PKL.</li><li>All inference checkpoint tensors must load. Only unused training LPIPS keys are excluded; missing or unexpected inference keys fail the trial.</li><li>Native helper bodies perform cropping/camera setup. Native forward, hand-offset clamp, deformer and renderer math are retained.</li></ul></div><div><h3>First failure → scoped repair</h3><p>The first run generated attributes but failed at rendering: the pinned rasterizer <code>main</code> revision lacked the antialiasing API. We did not remove antialiasing or discard the failed attempt.</p><p>The official <a href="https://github.com/graphdeco-inria/gaussian-splatting/blob/main/.gitmodules">3DGS submodule configuration</a> uses <code>dr_aa</code>. We pinned <a href="https://github.com/graphdeco-inria/diff-gaussian-rasterization/tree/9c5c2028f6fbee2be239bc4c9421ff894fe4fbe0">that implementation</a>, rebuilt it only in IDOL's volume, and added an API check before expensive loading.</p><p class="small">Code, checkpoint, Sapiens, body models, renderer and input media have separate terms. A public download or license badge is not commercial clearance.</p></div></div></section>
<section><div class="section-label">05 / Research decision</div><h2>Advance the evidence, not the default.</h2><ol><li><strong>Freeze a consented evaluation set.</strong> Matched real photos and unseen views; none of these bundled smoke cases establish identity fidelity or back-view accuracy.</li><li><strong>Compare native quality fairly.</strong> LHM 500M/1B, LHM++ 1/4/8 views, and IDOL with documented preprocessing and shape sources. Do not call plausible unseen details recovered truth.</li><li><strong>Timebox an IDOL portability spike only if warranted.</strong> Define the new covariance/scale/pose-corrective contract, measure payload/runtime costs, then reproduce its own native fixtures in a clean browser after generation exits.</li><li><strong>Keep LHM as the default.</strong> LHM++ remains the implemented multi-photo web option. DiGS is conditional on a usable pretrained release; no new DiGS execution is claimed here.</li></ol><p><a href="../../../../generation-experiments-plan.md">Full experiment plan</a> · <a href="../web-mvp-20260908/index.html">Working LHM++ web MVP evidence</a> · <a href="../../idol/README.md">IDOL reproduction guide</a> · <a href="summary.json">Report ledger</a></p></section>
</main><footer>Local engineering evidence · single workstation · actual native renders, not generated illustrations. No held-out PSNR/SSIM/LPIPS, blind preference ranking, or commercial-use approval.</footer></body></html>'''
    for key, value in {'DECISION': escape(decision), 'PASSED': str(len(passed)), 'TOTAL': str(len(records)),
                       'RUNS': sections, 'BASIS': f'{pose_basis:.1f}', 'EXPANDED': f'{expanded:.1f}'}.items():
        body = body.replace('@@' + key + '@@', value)
    if not passed: body = body.replace('IDOL runs natively.', 'IDOL native trial.')
    if args.portability_run:
        if not re.fullmatch(r'portability-\d{8}-\d{6}-[0-9a-f]{6}', args.portability_run): raise ValueError('Invalid portability run ID')
        later = ROOT / args.portability_run
        if not (later / 'index.html').is_file(): raise ValueError('Build the portability report first')
        ledger = json.loads((later / 'summary.json').read_text())
        summary['correctiveStageFollowup'] = args.portability_run
        notice = f'<p class="notice"><strong>Later portability result:</strong> a {ledger["runtimeCorrectionBytes"]/1e6:.2f} MB corrective package passes {ledger["browserCases"]} native-reference cases in WebGPU. This remains a partial stage, not a full IDOL browser avatar. <a href="{args.portability_run}/index.html">Read the compact-corrective report →</a></p>'
        # Content placeholders have already been resolved; insert immediately after the hero.
        body = body.replace('<section><div class="section-label">01 / What was executed', notice+'<section><div class="section-label">01 / What was executed', 1)
    (ROOT / 'index.html').write_text(body, encoding='utf-8')
    (ROOT / 'summary.json').write_text(json.dumps(summary, indent=2), encoding='utf-8')
    print(json.dumps(summary, indent=2))


if __name__ == '__main__': main()
